23	  std::unique_ptr<ContextHolderImpl> BuildTilingContext() {
24	    GE_ASSERT_NOTNULL(tiling_info_.compile_info_, "Compile info is nullptr");
25	    GE_ASSERT_NOTNULL(tiling_info_.platform_info_, "Platform info is nullptr");
26	
27	    auto holder = ge::ComGraphMakeUnique<ContextHolderImpl>();
28	    GE_ASSERT_NOTNULL(holder, "Create ContextHolderImpl failed.");
29	    GE_ASSERT_SUCCESS(CreateComputeNodeInfo(*holder), "Create compute node info failed.");
30	    for (auto &outvaue : output_values_) {
31	      (void)input_values_.emplace_back(outvaue.first, outvaue.second);
32	    }
33	    (void)input_values_.emplace_back(tiling_info_.compile_info_, nullptr);   // TilingCompileInfo
34	    (void)input_values_.emplace_back(tiling_info_.platform_info_, nullptr);  // PlatformInfo
35	    (void)input_values_.emplace_back(nullptr, nullptr);                      // PrepareTilingFrameworkData
36	    (void)input_values_.emplace_back(reinterpret_cast<void *>(tiling_info_.deterministic_), nullptr);  // Deterministic
37	    (void)input_values_.emplace_back(reinterpret_cast<void *>(tiling_info_.deterministic_level_),
38	                                     nullptr);  // DeterministicLevel
39	    output_values_.resize(TilingContext::kOutputNum);
40	    output_values_[TilingContext::kOutputTilingData] =
41	        std::make_pair(tiling_info_.tiling_data_.first, tiling_info_.tiling_data_.second);
42	    output_values_[TilingContext::kOutputWorkspace] = std::make_pair(tiling_info_.workspace_, nullptr);
43	    output_values_[TilingContext::kOutputSimtBlockDim] = std::make_pair(tiling_info_.simt_block_dim, nullptr);
44	    output_values_[TilingContext::kOutputSimtGridDim] = std::make_pair(tiling_info_.simt_grid_dim, nullptr);
45	    GE_ASSERT_SUCCESS(BuildCtx(*holder), "BuildCtx failed.");
46	    return holder;
47	  }
48	};
